import threading
import time
import weakref
from collections import defaultdict
from functools import wraps


class TokenBucket:
    """Rate limiter using token bucket algorithm."""
    def __init__(self, capacity, refill_rate):
        self.capacity = capacity
        self.tokens = capacity
        self.refill_rate = refill_rate
        self.last_refill = time.monotonic()
        self._lock = threading.Lock()
        self._callbacks = []

    def _refill(self):
        now = time.monotonic()
        elapsed = now - self.last_refill
        self.tokens = min(self.capacity, self.tokens + elapsed * self.refill_rate)
        self.last_refill = now

    def consume(self, n=1):
        with self._lock:
            self._refill()
            if self.tokens >= n:
                self.tokens -= n
                return True
            return False

    def register_callback(self, cb):
        self._callbacks.append(cb)

    def notify_exhaustion(self):
        for cb in self._callbacks:
            cb()


class SessionContext:
    """Holds per-request session data and cleanup handlers."""
    def __init__(self, session_id, user_data):
        self.session_id = session_id
        self.user_data = user_data
        self._finalizers = []
        self._disposed = False

    def add_finalizer(self, fn):
        self._finalizers.append(fn)

    def dispose(self):
        self._disposed = True
        for fn in self._finalizers:
            fn()
        self._finalizers.clear()
        self.user_data = None

    @property
    def is_active(self):
        return not self._disposed


class RetryableRequest:
    """Wraps a request with retry logic and rate limit awareness."""
    def __init__(self, handler, session_ctx, rate_limiter):
        self._handler = handler
        self._session_ref = weakref.ref(session_ctx)
        self._rate_limiter = rate_limiter
        self._max_retries = 3
        self._retry_delay = 0.01

    def execute(self, *args, **kwargs):
        attempts = 0
        last_error = None

        while attempts < self._max_retries:
            if not self._rate_limiter.consume():
                time.sleep(self._retry_delay)
                attempts += 1
                continue

            try:
                session = self._session_ref()
                if session is None:
                    raise RuntimeError("Session garbage collected")
                if not session.is_active:
                    raise RuntimeError("Session was disposed")
                result = self._handler(session, *args, **kwargs)
                return result
            except TransientError as e:
                last_error = e
                attempts += 1
                time.sleep(self._retry_delay)
            except Exception as e:
                raise

        raise RetryExhaustedError(f"Failed after {attempts} attempts: {last_error}")


class TransientError(Exception):
    pass


class RetryExhaustedError(Exception):
    pass


class RequestDispatcher:
    """Dispatches incoming requests with rate limiting and session management."""
    def __init__(self):
        self._limiters = defaultdict(lambda: TokenBucket(10, 2.0))
        self._active_sessions = {}
        self._lock = threading.Lock()

    def _create_session(self, user_id, request_data):
        session = SessionContext(f"sess_{user_id}_{time.monotonic()}", request_data)
        with self._lock:
            # Store session; old session for same user gets disposed
            old = self._active_sessions.get(user_id)
            if old is not None:
                old.dispose()
            self._active_sessions[user_id] = session
        return session

    def handle_request(self, user_id, request_data, handler):
        limiter = self._limiters[user_id]
        session = self._create_session(user_id, request_data)

        retryable = RetryableRequest(handler, session, limiter)
        return retryable.execute()


def process_user_action(session, action_type="default"):
    """Business logic handler that uses session data."""
    if not session.is_active:
        raise TransientError("Session inactive, retry")

    # Simulate processing that accesses user_data
    data = session.user_data
    if data is None:
        raise TransientError("No data available")

    result = {
        "session_id": session.session_id,
        "action": action_type,
        "processed": data.get("payload", "") + "_processed"
    }
    return result


def main():
    dispatcher = RequestDispatcher()

    request_data = {"payload": "user_action_data", "token": "secret_abc123"}

    try:
        result = dispatcher.handle_request("user42", request_data, process_user_action)
        print(f"Success: {result}")
    except RetryExhaustedError as e:
        print(f"Failed: {e}")


if __name__ == "__main__":
    main()
